import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { scykRoutes } from '../../config/scykRoutes';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchIncidentPublicReportById,
  confirmIncidentPublicReport,
  rejectIncidentPublicReport,
  setSelectedPublicReport,
} from '../../store/slices/incidentPublicReportsSlice';
import { addToast } from '../../store/slices/uiSlice';
import { IncidentPublicReportStatus } from '../../models/IncidentPublicReport';
import { useFormOptions } from '../../hooks/useFormOptions';
import { useIncidentPublicReportPermissions } from '../../hooks/useIncidentPublicReportPermissions';
import { utcToLocalInputValue } from '../../utils/dateTime';
import { getApiErrorMessage } from '../../utils/apiMessages';
import styles from '../IncidentDetectionFormPage/IncidentDetectionFormPage.module.css';
import { Button } from '@linm-soft-org/linm-web-common-components';

const IncidentPublicReportStaffPage: React.FC = () => {
  const { id = '' } = useParams<{ id: string }>();
  const appNavigate = useAppNavigate();
  const dispatch = useAppDispatch();
  const { selected, saving, loading } = useAppSelector((s) => s.incidentPublicReports);
  const {
    publicReportLabel: L,
    publicReportStatusOptions,
    publicReportReporterKindOptions,
    patientGenderOptions,
  } = useFormOptions('create-public-report');
  const perms = useIncidentPublicReportPermissions();
  const [rejectOpen, setRejectOpen] = useState(false);
  const [rejectReason, setRejectReason] = useState('');

  const form = selected;
  const status = form?.status ?? '';
  const canAct = status === IncidentPublicReportStatus.Submitted;
  const statusLabel = publicReportStatusOptions.find((o) => o.value === status)?.label ?? status;
  const kindLabel = publicReportReporterKindOptions.find((o) => o.value === form?.reporterKind)?.label
    ?? form?.reporterKind ?? '';
  const genderLabel = patientGenderOptions.find((o) => o.value === form?.patientGender)?.label
    ?? form?.patientGender ?? '';

  useEffect(() => {
    const t = setTimeout(() => {
      if (id) dispatch(fetchIncidentPublicReportById(id));
      else dispatch(setSelectedPublicReport(null));
    }, 0);
    return () => clearTimeout(t);
  }, [dispatch, id]);

  const handleBack = () => appNavigate(scykRoutes.publicReports.list);

  const handleConfirm = async () => {
    try {
      const incident = await dispatch(confirmIncidentPublicReport(id)).unwrap();
      dispatch(addToast({ message: L('confirmSuccess'), type: 'success' }));
      appNavigate(scykRoutes.incidents.detail(incident.id));
    } catch (error: unknown) {
      dispatch(addToast({ message: getApiErrorMessage(error), type: 'error' }));
    }
  };

  const handleReject = async () => {
    if (!rejectReason.trim()) {
      dispatch(addToast({ message: L('rejectReasonRequired'), type: 'error' }));
      return;
    }
    try {
      await dispatch(rejectIncidentPublicReport({ id, reason: rejectReason.trim() })).unwrap();
      dispatch(addToast({ message: L('rejectSuccess'), type: 'success' }));
      setRejectOpen(false);
    } catch (error: unknown) {
      dispatch(addToast({ message: getApiErrorMessage(error), type: 'error' }));
    }
  };

  if (loading && !form) {
    return <div className={styles.loadingWrap}><i className="fas fa-spinner fa-spin" /> {L('loading')}</div>;
  }

  if (!form) {
    return (
      <div className={styles.page} data-testid="incident-public-report-staff-empty">
        <div className={styles.pageHeader}>
          <Button variant="secondary" onClick={handleBack}>{L('back')}</Button>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.page} data-testid="incident-public-report-staff">
      <div className={styles.stickyTop}>
        <div className={styles.pageHeader}>
          <div className={styles.titleGroup}>
            <button type="button" className={styles.backBtn} onClick={handleBack}>
              <i className="fas fa-arrow-left" />
            </button>
            <div>
              <h1 className={styles.title}>{L('staffTitle')}: {form.idCode}</h1>
              <p className={styles.subtitle}><span className={styles.badge}>{statusLabel}</span></p>
            </div>
          </div>
          <div className={styles.headerActions}>
            <Button variant="secondary" onClick={handleBack} disabled={saving}>{L('back')}</Button>
            {canAct && perms.canConfirm && (
              <Button variant="primary" onClick={handleConfirm} disabled={saving}>{L('confirm')}</Button>
            )}
            {canAct && perms.canReject && (
              <Button variant="danger" onClick={() => setRejectOpen(true)} disabled={saving}>{L('reject')}</Button>
            )}
            {status === IncidentPublicReportStatus.Confirmed && form.incidentId && (
              <Button variant="primary" onClick={() => appNavigate(scykRoutes.incidents.detail(form.incidentId!))}>
                {L('openIncident')}
              </Button>
            )}
          </div>
        </div>
      </div>

      <div className={styles.formBody}>
        <div className={styles.section}>
          <div className={styles.row}>
            <div className={styles.field}>
              <label>{L('idCode')}</label>
              <input readOnly disabled value={form.idCode} />
            </div>
            <div className={styles.field}>
              <label>{L('occurredAt')}</label>
              <input readOnly disabled value={utcToLocalInputValue(form.occurredAt)} />
            </div>
          </div>
          <div className={styles.row}>
            <div className={styles.field}>
              <label>{L('reporterKind')}</label>
              <input readOnly disabled value={kindLabel} />
            </div>
            <div className={styles.field}>
              <label>{L('reporterName')}</label>
              <input readOnly disabled value={form.reporterName} />
            </div>
          </div>
          <div className={styles.row}>
            <div className={styles.field}>
              <label>{L('reporterPhone')}</label>
              <input readOnly disabled value={form.reporterPhone} />
            </div>
            <div className={styles.field}>
              <label>{L('patientName')}</label>
              <input readOnly disabled value={form.patientName} />
            </div>
          </div>
          <div className={styles.row}>
            <div className={styles.field}>
              <label>{L('patientGender')}</label>
              <input readOnly disabled value={genderLabel} />
            </div>
            <div className={styles.field}>
              <label>{L('department')}</label>
              <input readOnly disabled value={form.departmentName} />
            </div>
          </div>
          <div className={styles.row}>
            <div className={styles.field}>
              <label>{L('areaText')}</label>
              <input readOnly disabled value={form.areaText ?? ''} />
            </div>
            <div className={styles.field}>
              <label>{L('colDevice')}</label>
              <input readOnly disabled value={form.deviceId ?? ''} />
            </div>
          </div>
          <div className={styles.field}>
            <label>{L('description')}</label>
            <textarea readOnly disabled rows={4} value={form.description} />
          </div>
          {form.incidentIdCode && (
            <div className={styles.field}>
              <label>{L('incidentCode')}</label>
              <input readOnly disabled value={form.incidentIdCode} />
            </div>
          )}
          {form.confirmedByName && (
            <div className={styles.field}>
              <label>{L('confirmedBy')}</label>
              <input readOnly disabled value={form.confirmedByName} />
            </div>
          )}
          {form.rejectReason && (
            <div className={styles.field}>
              <label>{L('rejectReason')}</label>
              <textarea readOnly disabled rows={2} value={form.rejectReason} />
            </div>
          )}
        </div>
      </div>

      {rejectOpen && (
        <div className={styles.overlay}>
          <div className={styles.dialog}>
            <h3>{L('reject')}</h3>
            <div className={styles.field}>
              <label>{L('rejectReason')} *</label>
              <textarea rows={3} value={rejectReason} onChange={(e) => setRejectReason(e.target.value)} />
            </div>
            <div className={styles.dialogActions}>
              <Button variant="secondary" onClick={() => setRejectOpen(false)}>{L('cancel')}</Button>
              <Button variant="danger" onClick={handleReject} disabled={saving}>{L('reject')}</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default IncidentPublicReportStaffPage;
